WITH lines AS (SELECT id, service, host, log_ts, level, status_code, attr_key, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) e AS attr_key, attr_value) SELECT service, DATE_TRUNC('HOUR', log_ts) AS hour_window, SORT_ARRAY(COLLECT_SET(level)) AS level_list, COUNT(*) FILTER (WHERE level = 'ERROR') AS error_rows, PERCENTILE_APPROX(status_code, 0.95) AS status_code_p95, ROUND(AVG(status_code), 2) AS avg_status_code, SUM(CASE WHEN level = 'DEBUG' THEN status_code ELSE 0 END) AS debug_status_code, COUNT_IF(host = 'h4') AS h4_events FROM lines GROUP BY service, hour_window HAVING status_code_p95 >= 0 ORDER BY debug_status_code DESC
